{
  "name": "all_pairs_gap_sigmoid_simple_v001",
  "intuition": "Use the fixed all-pairs topology and reweight pairs by a simple sigmoid on the nonnegative gap with central threshold and clamping, preserving the 'gap_sigmoid' weight family and avoiding instability by omitting extra tunable sharpness parameter.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "sigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Construct all pairs where winner's objective is less than loser's\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    # Compute positive gap (nonnegative)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = gap.clamp_min(0.0)\n    # Parameters for sigmoid weighting\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 2.0))\n    center = (clamp_lo + clamp_hi) / 2.0\n    # Sigmoid sharpness fixed to 10 for stable smoothness\n    sharpness = 10.0\n    # Compute sigmoid weight centered between clamp bounds\n    weight = 1.0 / (1.0 + (-(sharpness * (gap - center))).exp())\n    # Clamp final weights to specified range\n    weight = weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})"
}
