{
  "name": "all_pairs_gap_sigmoid_simple_v002",
  "intuition": "Weight all pairs with a sigmoid function centered on the nonnegative gap between loser and winner objectives, clamped to a configurable range, preserving the gap_sigmoid weight family and all-pairs topology exactly as required.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "sigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Construct all pairs where winner's objective is less than loser's\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # If no pairs, return empty PrefBatch\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    # Compute positive gap (loser_obj - winner_obj)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = gap.clamp_min(0.0)\n    # Read clamping bounds from extra, with defaults\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 2.0))\n    center = (clamp_lo + clamp_hi) * 0.5\n    sharpness = 10.0  # fixed sharpness for stable sigmoid\n    # Compute sigmoid weights centered at center: sigmoid(sharpness*(gap - center))\n    weight = 1.0 / (1.0 + (-(sharpness * (gap - center))).exp())\n    # Clamp weights explicitly in [clamp_lo, clamp_hi]\n    weight = weight.clamp(min=clamp_lo, max=clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})"
}
