  "name": "combined_pairwise_gap_sigmoid",
  "intuition": "This builder combines the all_pairs pair construction with a sigmoid-based weighting function to smoothly emphasize pairs with larger objective gaps, integrating the linear gap idea with a soft normalization to enhance robustness and control over pair contributions.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
