  "name": "all_pairs_gap_sigmoid_simple",
  "intuition": "Vectorized weighting all pairs by a sigmoid of the raw positive gap clipped between 0.25 and 3, avoiding per-instance normalization and loops",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid_clamped",
    "constraint_family": "clamp_only"
