    "sigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid_clamped'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Apply a sigmoid weighting directly to the gap with learned scale and shift from extra\n    beta = float(extra.get('weight_beta', 1.5))  # center shift of sigmoid\n    tau = float(extra.get('weight_tau', 3.0))    # sigmoid sharpness\n    weight_raw = (gap - beta) * tau\n    import torch\n    weight_sig = torch.sigmoid(weight_raw)\n    weight = weight_sig.clamp(0.25, 3.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid_clamped'})"
