  "name": "cross_reweight_gap_linear_sigmoid",
  "intuition": "Combines the linear gap weight from parent 1 with the sigmoid monotone transform and clamp behaviors from parent 2 to create a smooth, stable, nonnegative pairwise weight emphasizing moderate gaps while controlling extreme values.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_mixed_sigmoid",
    "constraint_family": "clamp_only"
