    "expects": ["objective", "log_prob", "obj_z", "rank", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Clamp gap to moderate range\n    raw = gap.clamp_min(0.0)\n    # Apply sigmoid to create smooth transition\n    weight = 1.0 / (1.0 + ops.exp(-raw + 0.5))\n    # Clamp to avoid extremes\n    weight = weight.clamp(0.1, 1.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'cross_reweight', 'weight_family': 'gap_mixed_sigmoid'})"
}

